        children: "def eval_postfix(expr):\r\n    stack = []\r\n    for token in expr:\r\n        if token.isdigit():\r\n            stack.append(int(token))\r\n        else:\r\n            b = stack.pop()\r\n            a = stack.pop()\r\n            if token == \"+\": stack.append(a + b)\r\n            elif token == \"-\": stack.append(a - b)\r\n            elif token == \"*\": stack.append(a * b)\r\n            elif token == \"/\": stack.append(a // b)\r\n    return stack[0]\r\n\r\nprint(eval_postfix(\"23*54*+\"))  # (2*3)+(5*4) = 26\n"
